contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: send an arbitrary amount to c.go and check invariants
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance to forward");

        // read owner before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        // call go with specified amount
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read owner and balances after
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balC = address(c).balance;
        uint256 balThis = address(this).balance;

        // General rule: owner never changes and c's balance is always zero after the call
        // (the contract's logic should forward any held Ether to owner regardless of external call outcome)
        assert(ownerBefore == ownerAfter && balC == 0);
    }

    receive() external payable {}
}

